using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using TMPro;using UnityEditor;using UnityEngine;using UnityEngine.UI;
namespace LuckyForge.Offline.Editor{
public static class HourlyRewardVerification{
 [Serializable]public class Result{public bool passed;public int checks;public string testRoot;public string saveFile;public List<string> failures=new List<string>();public List<string> sourceRules=new List<string>();}
 static void Check(Result r,bool ok,string s){r.checks++;if(!ok)r.failures.Add(s);}
 static object Call(object obj,string n,params object[] a)=>obj.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(obj,a);
 static void Set(object obj,string n,object v)=>obj.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(obj,v);
 static T Get<T>(object obj,string n)=>(T)obj.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(obj);
 static GameObject Child(Transform p,string n){var g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);return g;}
 static T Add<T>(Transform p,string n)where T:Component=>Child(p,n).AddComponent<T>();
 static SaatlikHediye Fixture(Transform root){var m=Add<SaatlikHediye>(root,"hourly-original");m.btnUstuSaat=new TextMeshProUGUI[7];m.rewardButtons=new Button[7];m.rewardNedir=new TextMeshProUGUI[7];m.titles=new TextMeshProUGUI[7];m.resetTimerText=Add<TextMeshProUGUI>(m.transform,"reset-time");m.infoBottom=Child(m.transform,"hourly-info");for(int i=0;i<7;i++){m.btnUstuSaat[i]=Add<TextMeshProUGUI>(m.transform,"claim-text"+i);m.rewardButtons[i]=Add<Button>(m.transform,"claim"+i);m.rewardNedir[i]=Add<TextMeshProUGUI>(m.transform,"amount"+i);m.titles[i]=Add<TextMeshProUGUI>(m.transform,"timer"+i);int index=i;m.rewardButtons[i].onClick.AddListener(()=>m.ClaimReward(index));}return m;}
 // Standard UI eligibility is the original source guard; do not directly invoke a disabled Button event.
 static bool ClickAvailable(SaatlikHediye m,int i){if(!m.rewardButtons[i].interactable)return false;m.rewardButtons[i].onClick.Invoke();return true;}
 static void Flush(Currencys driver){foreach(string name in new[]{"SaveEnergyTimer","SaveCoinTimer","SaveCrystalTimer"})typeof(Currencys).GetField(name,BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,-1f);Call(driver,"Update");ES3.StoreCachedFile("medupac.es3",new ES3Settings("medupac.es3",ES3.Location.File));OfflineKeyStore.ResetMemoryForVerification();ES3.CacheFile("medupac.es3",new ES3Settings("medupac.es3",ES3.Location.File));}
 public static Result RunChecks(string suppliedRoot=null){
  var r=new Result{testRoot=Path.GetFullPath(suppliedRoot??Path.Combine(Path.GetTempPath(),"LuckyForgeHourlyRewardChecks",Guid.NewGuid().ToString("N")))};
  if(EditorApplication.isPlayingOrWillChangePlaymode){r.failures.Add("Requires isolated non-playing Editor process.");return r;}Directory.CreateDirectory(r.testRoot);
  var saved=new Dictionary<FieldInfo,object>();foreach(var t in new[]{typeof(Currencys),typeof(SaatlikHediye),typeof(GameManager),typeof(Basarimlar),typeof(GunlukGorevler),typeof(MerdivenEventManager),typeof(ES3Cloud),typeof(OneTimeOffer),typeof(Lang)})foreach(var f in t.GetFields(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic))if(!f.IsLiteral&&!f.IsInitOnly)saved[f]=f.GetValue(null);
  var oldSound=SoundManager.instance;var root=new GameObject("HourlyRewardVerification");root.SetActive(false);OfflineKeyStore.SetVerificationRoot(r.testRoot);
  try{
   SoundManager.instance=null;GameManager.Language=0;Lang.currentLang=null;GameManager.GuideDone=false;GameManager.Level=0;GameManager.NewUserTapNation=true;Basarimlar.basarilar=new List<BasariGorev>();GunlukGorevler.tasks=new List<GunlukGorev>();
   var driver=Add<Currencys>(root.transform,"deferred-save-driver");Currencys.EnergyFitle(0);Currencys.CoinFitle(0);Currencys.CrystalFitle(0);
   var loader=Add<LoadingPage>(root.transform,"hourly-timestamp-loader");DateTime before=DateTime.UtcNow;Call(loader,"Events");
   Check(r,ES3.KeyExists("saatlikOdulReset")&&Math.Abs((SaatlikHediye.lastLoginTime-before).TotalSeconds)<3&&SaatlikHediye.totalSecondsSpentInGame==0,"original missing-key loader creates reset timestamp with zero elapsed online seconds");
   var m=Fixture(root.transform);m.Awaker();Call(m,"OnEnable");
   var intervals=Get<TimeSpan[]>(m,"rewardIntervals");Check(r,intervals.Select(t=>t.TotalSeconds).SequenceEqual(new double[]{240,480,720,1200,1800,3000,5400})&&Get<TimeSpan>(m,"resetTime")==TimeSpan.FromHours(4),"all7 exact native online thresholds and4hour rolling reset");
   Check(r,m.collectedOrNot.Length==7&&m.collectedOrNot.All(v=>!v)&&Get<TimeSpan[]>(m,"rewardTimers").SequenceEqual(intervals),"Awaker creates7 timers and source false fallback flags");
   Check(r,m.rewardNedir.Take(6).All(t=>t.text=="<sprite=3>10")&&m.rewardNedir[6].text=="<sprite=3>20","all original energy reward amounts rendered exactly");
   Call(m,"Update");Check(r,m.rewardButtons.All(b=>!b.interactable)&&m.btnUstuSaat.All(t=>t.text==Lang.Get.waiting)&&m.titles[0].text=="<sprite=4>4"+Lang.Get.kisaltmadakika+" 0"+Lang.Get.kisaltmasaniye,"initial waiting labels disable actual claim buttons");
   Check(r,!ClickAvailable(m,0)&&Currencys.Energy==0&&!m.IsAnyRewardClaimable(),"unearned normal UI click and stored indicator grant nothing");
   var tabs=Add<GunlukHediye>(root.transform,"daily-hourly-tabs");tabs.insidePages=new[]{Child(tabs.transform,"daily-page"),m.gameObject};tabs.bottomBtns=new[]{Child(tabs.transform,"daily-tab"),Child(tabs.transform,"hourly-tab")};tabs.bottomBtns[1].transform.position=new Vector3(4f,5f,6f);tabs.bottombtnlight=Child(tabs.transform,"selector").transform;tabs.OpenInsidePage(1);Check(r,m.gameObject.activeSelf&&!tabs.insidePages[0].activeSelf&&tabs.bottombtnlight.position==tabs.bottomBtns[1].transform.position,"original tab callback selects hourly page and moves tab highlight");
   var gm=Add<GameManager>(root.transform,"restored-time-accumulator");gm.warController=Add<WarController>(root.transform,"battle-state");gm._offer=Add<OneTimeOffer>(root.transform,"non-granting-offer");GameManager.basarimlar=0;gm.timekazanchesapla=0;SaatlikHediye.totalSecondsSpentInGame=10f;float dt=Time.deltaTime;Call(gm,"Update");Check(r,SaatlikHediye.totalSecondsSpentInGame==(float)(10f+dt),"restored GameManager.Update is sole actual online time accumulator");
   SaatlikHediye.totalSecondsSpentInGame=239f;Call(m,"Update");Check(r,!m.rewardButtons[0].interactable&&!ClickAvailable(m,0)&&m.titles[0].text.EndsWith("1"+Lang.Get.kisaltmasaniye),"239seconds remains below first4minute threshold");
   SaatlikHediye.totalSecondsSpentInGame=240f;Call(m,"Update");Check(r,!m.rewardButtons[0].interactable&&Get<TimeSpan[]>(m,"rewardTimers")[0]==TimeSpan.Zero,"source positive timer branch reaches0 but remains disabled for this frame");Call(m,"Update");Check(r,m.rewardButtons[0].interactable&&m.btnUstuSaat[0].text==Lang.Get.al&&m.titles[0].text=="<sprite=4>00:00","next frame exact threshold enables original normal claim");
   Check(r,!m.IsAnyRewardClaimable(),"indicator deliberately reads saved seconds0 rather than live static240");ES3.Save<float>("saatlikOdulSaniyeToplam",240f);Check(r,m.IsAnyRewardClaimable(),"persisted threshold enables original claimable indicator");
   Check(r,ClickAvailable(m,0)&&Currencys.Energy==10&&m.collectedOrNot[0]&&ES3.Load<bool[]>("SaatlikHediyeCollectedOrNot")[0],"ordinary button grants10Energy and immediately persists first collected flag");
   Check(r,!ClickAvailable(m,0)&&Currencys.Energy==10&&!m.IsAnyRewardClaimable()&&!m.infoBottom.activeSelf,"disabled collected button rejects normal repeat, clears indicator and does not regrant");
   Flush(driver);Currencys.EnergyFitle(0);OfflineKeyStore.ResetMemoryForVerification();ES3.CacheFile("medupac.es3",new ES3Settings("medupac.es3",ES3.Location.File));Currencys.LoadStartEnergy();Call(loader,"Events");var restored=Fixture(root.transform);restored.Awaker();Call(restored,"Update");
   Check(r,Currencys.Energy==10&&restored.collectedOrNot[0]&&!restored.rewardButtons[0].interactable&&SaatlikHediye.totalSecondsSpentInGame==240f,"physical reload plus actual startup timestamp loading preserves earned Energy/time and claimed flag");Check(r,!ClickAvailable(restored,0)&&Currencys.Energy==10,"fresh manager normal UI cannot reclaim physically saved first reward");
   m=restored;for(int i=1;i<7;i++){SaatlikHediye.totalSecondsSpentInGame=(float)intervals[i].TotalSeconds;ES3.Save<float>("saatlikOdulSaniyeToplam",SaatlikHediye.totalSecondsSpentInGame);Call(m,"Update");Call(m,"Update");Check(r,m.rewardButtons[i].interactable&&ClickAvailable(m,i),"earned normal reward threshold index"+i);int expected=i==6?80:(i+1)*10;Check(r,Currencys.Energy==expected&&!ClickAvailable(m,i),"source reward amount and no normal duplicate index"+i);}
   Check(r,m.collectedOrNot.All(v=>v)&&!m.IsAnyRewardClaimable()&&Currencys.Energy==80,"seven ordinary earned rewards total80Energy and all claimed indicator clears");Flush(driver);Currencys.LoadStartEnergy();Call(loader,"Events");var allReloaded=Fixture(root.transform);allReloaded.Awaker();Call(allReloaded,"Update");Check(r,allReloaded.collectedOrNot.All(v=>v)&&allReloaded.rewardButtons.All(b=>!b.interactable)&&Currencys.Energy==80,"all7 collected flags and80Energy survive another actual disk reload");
   SaatlikHediye.lastLoginTime=DateTime.UtcNow.AddHours(-3);Call(allReloaded,"Update");Check(r,allReloaded.collectedOrNot.All(v=>v)&&SaatlikHediye.totalSecondsSpentInGame==5400f,"3hour wallclock does not reset source4hour cycle");
   SaatlikHediye.lastLoginTime=DateTime.UtcNow.AddHours(-4).AddSeconds(-1);Call(allReloaded,"Update");Check(r,SaatlikHediye.totalSecondsSpentInGame==0&&allReloaded.collectedOrNot.All(v=>!v)&&ES3.Load<float>("saatlikOdulSaniyeToplam")==0&&ES3.Load<bool[]>("SaatlikHediyeCollectedOrNot").All(v=>!v),"4hour expiry resets cumulative online time and all7 actual saved flags");
   Check(r,Get<TimeSpan[]>(allReloaded,"rewardTimers").SequenceEqual(intervals)&&allReloaded.rewardButtons.All(b=>!b.interactable)&&Currencys.Energy==80,"reset restarts original timers without deducting or granting resources");
   Check(r,DateTime.TryParse(ES3.Load<string>("saatlikOdulReset"),out var resetDate)&&Math.Abs((resetDate-DateTime.UtcNow).TotalSeconds)<3,"reset persists actual UTC default-format timestamp");
   Call(allReloaded,"Update");Check(r,!ClickAvailable(allReloaded,0)&&!allReloaded.IsAnyRewardClaimable(),"new cycle requires earning online time again before normal reward");
   ES3.Save<float>("saatlikOdulSaniyeToplam",12f);ES3.Save<string>("saatlikOdulReset",DateTime.UtcNow.AddHours(-2).ToString());Call(loader,"Events");var noOffline=Fixture(root.transform);noOffline.Awaker();Call(noOffline,"Update");Check(r,SaatlikHediye.totalSecondsSpentInGame==12f&&!noOffline.IsAnyRewardClaimable()&&!ClickAvailable(noOffline,0),"2hours of offline wallclock never credit this online-only time track");
   ES3.Save<string>("saatlikOdulReset","invalid-source-date");Call(loader,"Events");Check(r,ES3.Load<string>("saatlikOdulReset")=="invalid-source-date"&&Math.Abs((SaatlikHediye.lastLoginTime-DateTime.UtcNow).TotalSeconds)<3,"source invalid date uses UTC fallback without rewriting saved malformed string");
   r.saveFile=OfflineKeyStore.PathFor();Flush(driver);Check(r,File.Exists(r.saveFile),"actual isolated physical hourly save exists");r.sourceRules.Add("7 original thresholds4/8/12/20/30/50/90min,6x10+20Energy;4hour reset. No offline elapsed credit, ads, payment or multipliers.");r.sourceRules.Add("ClaimReward original has no direct-call guard. Fixture follows source Button.interactable gate; no claim of physical mouse testing or reflection API idempotence.");
  }catch(Exception e){r.failures.Add(e.ToString());}finally{foreach(var kv in saved)kv.Key.SetValue(null,kv.Value);SoundManager.instance=oldSound;OfflineKeyStore.SetVerificationRoot(null);UnityEngine.Object.DestroyImmediate(root);}
  r.passed=r.failures.Count==0;File.WriteAllText(Path.Combine(r.testRoot,"hourly-reward-results.json"),JsonUtility.ToJson(r,true));Debug.Log("HourlyRewardVerification checks="+r.checks+" passed="+r.passed+" root="+r.testRoot);return r;
 }
